@extends('layouts.app')

@section('title', 'Jelajahi - TransitTrip Yogyakarta')

@section('content')
<div id="map" class="w-full" style="height: calc(var(--vh, 1vh) * 100 - 52px);"></div>
@endsection

@push('scripts')
<script>
var map, poiCluster, transitRoutesLayer, transitStopsLayer, transitRadiusLayer;

function initMap() {
    if (map) return;

    // Fix mobile viewport height
    var vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', vh + 'px');
    window.addEventListener('resize', function() {
        var vh = window.innerHeight * 0.01;
        document.documentElement.style.setProperty('--vh', vh + 'px');
    });

    var isMobile = window.innerWidth < 768;

    map = L.map('map', {
        center: [-7.805, 110.378],
        zoom: isMobile ? 13 : 14,
        zoomControl: !isMobile,
        attributionControl: !isMobile,
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a> contributors',
        maxZoom: 19,
    }).addTo(map);

    // Mobile: add zoom control in bottom-right
    if (isMobile) {
        L.control.zoom({ position: 'bottomright' }).addTo(map);
    }

    // Marker cluster
    poiCluster = L.markerClusterGroup({
        chunkedLoading: true,
        spiderfyOnEveryZoom: true,
        maxClusterRadius: isMobile ? 60 : 50,
        disableClusteringAtZoom: isMobile ? 15 : 16,
    });

    // Transit stops layer group (for toggle)
    transitStopsLayer = L.layerGroup();
    transitRadiusLayer = L.layerGroup();
    transitRoutesLayer = L.layerGroup();

    loadPois();
    loadTransitStops();
    loadTransitRoutes();

    // Layer control - collapsible on mobile
    L.control.layers(null, {
        'Rute Transit': transitRoutesLayer,
        'Halte': transitStopsLayer,
        'Radius 500m': transitRadiusLayer
    }, { collapsed: isMobile }).addTo(map);
}

function loadPois(filters) {
    if (!poiCluster) return;
    poiCluster.clearLayers();

    var url = '/api/v1/pois?per_page=200';
    if (filters) url += filters;

    fetch(url)
        .then(function(res) { return res.json(); })
        .then(function(response) {
            var pois = response.data || [];
            pois.forEach(function(poi) {
                var lat = parseFloat(poi.latitude);
                var lng = parseFloat(poi.longitude);
                if (isNaN(lat) || isNaN(lng)) return;

                var iconHtml = poi.photo_url
                    ? '<div class="photo-marker" style="background-image:url(' + poi.photo_url + ')"></div>'
                    : '<span style="font-size:1.35rem;line-height:1;display:block;text-align:center;filter:drop-shadow(0 1px 2px rgba(0,0,0,0.3))">' + (poi.category?.icon || 'POI') + '</span>';

                var marker = L.marker([lat, lng], {
                    icon: L.divIcon({
                        className: 'poi-marker',
                        html: iconHtml,
                        iconSize: poi.photo_url ? [40, 40] : [32, 32],
                        iconAnchor: poi.photo_url ? [20, 20] : [16, 16],
                    }),
                });

                marker.bindTooltip(poi.name || 'POI', { direction: 'top', offset: [0, -18] });
                marker.on('click', function() {
                    window.dispatchEvent(new CustomEvent('poi-selected', { detail: poi }));
                });

                poiCluster.addLayer(marker);
            });

            if (!map.hasLayer(poiCluster)) map.addLayer(poiCluster);
        })
        .catch(function(err) {
          console.error('Failed to load POIs:', err);
          window.dispatchEvent(new CustomEvent('load-error', { detail: { message: err.message || 'Gagal memuat POI' } }));
        });
}

function loadTransitStops() {
    fetch('/api/v1/transit-stops')
        .then(function(res) { return res.json(); })
        .then(function(response) {
            var stops = response.data || [];
            (Array.isArray(stops) ? stops : []).forEach(function(stop) {
                var lat = parseFloat(stop.latitude);
                var lng = parseFloat(stop.longitude);
                if (isNaN(lat) || isNaN(lng)) return;

                // Radius 500m
                var radius = L.circle([lat, lng], {
                    radius: 500,
                    dashArray: '4 8',
                    opacity: 0.08,
                    fillOpacity: 0.05,
                    color: '#1a3a4a',
                    fillColor: '#1a3a4a',
                    interactive: false,
                });
                transitRadiusLayer.addLayer(radius);

                // Stop dot
                var dot = L.circleMarker([lat, lng], {
                    radius: 6,
                    fillColor: '#1a3a4a',
                    color: '#f5a623',
                    weight: 2,
                    fillOpacity: 0.85,
                }).bindTooltip(stop.name || 'Halte', { direction: 'top' });
                transitStopsLayer.addLayer(dot);
            });

            // Add to map
            transitStopsLayer.addTo(map);
            transitRadiusLayer.addTo(map);
        })
        .catch(function(err) { console.error('Failed to load transit stops:', err); });
}

function loadTransitRoutes() {
    if (transitRoutesLayer) map.removeLayer(transitRoutesLayer);

    fetch('/api/v1/transit-routes')
        .then(function(res) { return res.json(); })
        .then(function(response) {
            var data = response.data && typeof response.data === 'object' ? response.data : response;

            L.geoJSON(data, {
                style: { color: '#f5a623', weight: 4, opacity: 0.7 },
                onEachFeature: function(feature, layer) {
                    if (feature.properties?.name) {
                        layer.bindTooltip(feature.properties.name, { direction: 'top' });
                    }
                },
            }).eachLayer(function(l) { transitRoutesLayer.addLayer(l); });

            transitRoutesLayer.addTo(map);

            if (transitRoutesLayer.getBounds && transitRoutesLayer.getBounds().isValid()) {
                map.fitBounds(transitRoutesLayer.getBounds(), { padding: [50, 50], maxZoom: 15 });
            }
        })
        .catch(function(err) { console.error('Failed to load transit routes:', err); });
}

function refreshMap() {
    var filters = Alpine.store('filters');
    if (!filters) { loadPois(); return; }
    var qs = filters.toQueryString ? filters.toQueryString() : '';
    loadPois(qs);
}

document.addEventListener('DOMContentLoaded', function() {
    initMap();
});

window.refreshMap = refreshMap;
window.loadPois = loadPois;
</script>

<style>
.poi-marker { background: none !important; border: none !important; box-shadow: none !important; }
.poi-marker .photo-marker { width:36px;height:36px;border-radius:50%;border:2px solid #fff;background-size:cover;background-position:center;box-shadow:0 2px 6px rgba(0,0,0,0.3); }
.leaflet-top { margin-top: 0.5rem; }
.leaflet-control-layers { font-size: 12px; border-radius: 10px !important; overflow: hidden; }
.leaflet-control-zoom { border-radius: 10px !important; overflow: hidden; }
.leaflet-control-zoom a { width: 36px !important; height: 36px !important; line-height: 36px !important; font-size: 18px !important; }
@media (max-width: 767px) {
    .leaflet-control-layers { font-size: 11px; }
    .leaflet-control-attribution { font-size: 9px !important; }
}
</style>
@endpush

{{-- POI Detail Popup / Overlay --}}
<div
  x-data="popupState()"
  x-show="selectedPoi != null"
  x-on:poi-selected.window="onPoiSelected($event.detail.poi)"
  x-on:keydown.escape.window="closePopup"
  class="fixed inset-0 z-50 flex items-end sm:items-center justify-center"
  x-cloak
>
  {{-- Backdrop --}}
  <div
    x-show="selectedPoi != null"
    x-transition:enter="transition-opacity duration-200"
    x-transition:leave="transition-opacity duration-150"
    class="absolute inset-0 bg-black/50 backdrop-blur-sm"
    @click="closePopup"
  ></div>

  {{-- Modal: bottom sheet on mobile, centered on desktop --}}
  <div
    x-show="selectedPoi != null"
    x-transition:enter="transition-all duration-300 ease-out"
    x-transition:enter-start="opacity-0 translate-y-8 sm:translate-y-4 sm:scale-95"
    x-transition:enter-end="opacity-100 translate-y-0 sm:scale-100"
    x-transition:leave="transition-all duration-200 ease-in"
    x-transition:leave-start="opacity-100 translate-y-0 sm:scale-100"
    x-transition:leave-end="opacity-0 translate-y-8 sm:translate-y-4 sm:scale-95"
    class="relative w-full sm:max-w-md max-h-[85vh] sm:max-h-[90vh] overflow-y-auto bg-white dark:bg-gray-900 rounded-t-2xl sm:rounded-2xl shadow-2xl border border-gray-200 dark:border-gray-700"
  >
    {{-- Mobile drag handle --}}
    <div class="sm:hidden flex justify-center pt-2 pb-1">
      <div class="w-10 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></div>
    </div>
    {{-- Close Button --}}
    <button
      @click="closePopup"
      class="absolute top-3 right-3 z-10 w-8 h-8 bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm rounded-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 hover:bg-white dark:hover:bg-gray-700 shadow-sm transition-all"
    >
      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
      </svg>
    </button>

    {{-- Photo / Hero --}}
    <div class="w-full h-48 bg-gradient-to-br from-emerald-100 via-teal-100 to-cyan-100 dark:from-emerald-900/50 dark:via-teal-900/30 dark:to-cyan-900/20 flex items-center justify-center relative overflow-hidden">
      <template x-if="selectedPoi.photo_url">
        <img :src="selectedPoi.photo_url" :alt="selectedPoi.name" class="w-full h-full object-cover" />
      </template>
      <template x-if="!selectedPoi.photo_url">
        <span class="text-7xl opacity-60 select-none" x-html="getCategoryIcon(selectedPoi.category?.slug)"></span>
      </template>

      {{-- Category Badge --}}
      <template x-if="selectedPoi.category">
        <div class="absolute top-3 left-3">
          <span class="px-2.5 py-1 text-xs font-semibold rounded-lg bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm text-gray-700 dark:text-gray-300 shadow-sm border border-white/50 dark:border-gray-700/50 flex items-center gap-1.5">
            <span x-html="getCategoryIcon(selectedPoi.category.slug)"></span>
            <span x-text="selectedPoi.category.name"></span>
          </span>
        </div>
      </template>
    </div>

    {{-- Content --}}
    <div class="p-5 space-y-4">
      {{-- Name & Transit Score --}}
      <div class="flex items-start justify-between gap-3">
        <div class="min-w-0">
          <h2 class="text-lg font-bold text-gray-900 dark:text-gray-100 leading-snug" x-text="selectedPoi.name"></h2>
          <p x-show="selectedPoi.address" class="text-xs text-gray-400 dark:text-gray-500 mt-1 truncate" x-text="selectedPoi.address"></p>
        </div>
        <template x-if="selectedPoi.transit_friendliness_score != null">
          <div class="flex-shrink-0 text-center">
            <div
              :class="scoreColor(selectedPoi.transit_friendliness_score)"
              class="w-14 h-14 rounded-xl flex flex-col items-center justify-center shadow-sm"
            >
              <span class="text-lg font-bold leading-none" x-text="selectedPoi.transit_friendliness_score"></span>
              <span class="text-[9px] font-medium mt-0.5 opacity-80">Skor</span>
            </div>
          </div>
        </template>
      </div>

      {{-- Description --}}
      <template x-if="selectedPoi.description">
        <p class="text-sm text-gray-600 dark:text-gray-400 leading-relaxed" x-text="selectedPoi.description"></p>
      </template>

      {{-- Detail Rows --}}
      <div class="space-y-2.5 bg-gray-50 dark:bg-gray-800/50 rounded-xl p-3.5">
        {{-- Operating Hours --}}
        <template x-if="selectedPoi.operating_hours">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Jam Buka</span>
            <span class="text-gray-800 dark:text-gray-200 font-medium" x-text="selectedPoi.operating_hours"></span>
          </div>
        </template>

        {{-- Price Range --}}
        <template x-if="selectedPoi.price_range">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Harga</span>
            <span class="text-gray-800 dark:text-gray-200 font-medium" x-text="priceLabel(selectedPoi.price_range)"></span>
          </div>
        </template>

        {{-- Nearest Stop --}}
        <div class="flex items-center gap-3 text-sm">
          <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/>
          </svg>
          <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Halte</span>
          <span class="text-gray-800 dark:text-gray-200 font-medium">
            <template x-if="selectedPoi.nearest_stop">
              <span>
                <span x-text="selectedPoi.nearest_stop.name"></span>
                <span class="text-gray-400 dark:text-gray-500 font-normal">
                  (<span x-text="selectedPoi.nearest_stop.distance_meters"></span> m · <span x-text="selectedPoi.nearest_stop.walking_minutes"></span> mnt jalan)
                </span>
              </span>
            </template>
            <template x-if="!selectedPoi.nearest_stop">
              <span class="text-gray-400 dark:text-gray-500 font-normal">Tidak tersedia</span>
            </template>
          </span>
        </div>

        {{-- Transit Score Detail --}}
        <template x-if="selectedPoi.transit_friendliness_score != null">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
