{{-- TransitTrip Sidebar Panel — populated by Alpine.js or map/index.blade.php --}}
<div x-data="sidebarState()" class="p-4">
    <h2 class="text-lg font-semibold text-[#1a3a4a] mb-1">Jelajahi Yogyakarta</h2>
    <p class="text-sm text-gray-500 mb-4">Temukan tempat menarik dan rute transit di sekitar Yogyakarta.</p>

    {{-- POI list placeholder — akan diisi oleh JS --}}
    <div id="poi-list" class="space-y-2">
        <p class="text-sm text-gray-400 italic">Memuat data POI…</p>
    </div>
</div>

<script>
    function sidebarState() {
        return {
            selectedPoi: null,
            poiList: [],
            init() {
                const self = this;
                window.addEventListener('poi-selected', function (e) {
                    self.selectedPoi = e.detail;
                });
            },
        };
    }

    /* Populate POI list from API */
    document.addEventListener('DOMContentLoaded', function () {
        const list = document.getElementById('poi-list');
        if (!list) return;

        fetch('/api/v1/pois')
            .then(res => res.json())
            .then(response => {
                const pois = response.data || [];
                if (pois.length === 0) {
                    list.innerHTML = '<p class="text-sm text-gray-400 italic">Belum ada POI tersedia.</p>';
                    return;
                }
                list.innerHTML = pois.slice(0, 20).map(poi => `
                    <button type="button"
                            class="w-full text-left p-3 rounded-lg border border-gray-200 hover:border-[#f5a623] hover:shadow-sm transition-all cursor-pointer"
                            onclick="window.dispatchEvent(new CustomEvent('poi-selected', {detail: ${JSON.stringify(poi).replace(/"/g, '&quot;')}}))">
                        <div class="flex items-center gap-2">
                            <span class="text-xl">${poi.category?.icon || '📍'}</span>
                            <div class="min-w-0">
                                <div class="text-sm font-medium text-gray-800 truncate">${poi.name || 'Tanpa Nama'}</div>
                                <div class="text-xs text-gray-400 truncate">${poi.category?.name || '—'}</div>
                            </div>
                        </div>
                    </button>
                `).join('');
            })
            .catch(() => {
                list.innerHTML = '<p class="text-sm text-red-500 italic">Gagal memuat POI.</p>';
            });
    });
</script>

